local UIWorldBossPlayerRankNode = Class('UIWorldBossPlayerRankNode')

function UIWorldBossPlayerRankNode:__init()
    self._data = nil
    self._isMe = false                     --是否是自己
    self._commonPlayerHeadNodeScr = nil
end

function UIWorldBossPlayerRankNode:__delete()
    self._data = nil
    self._isMe = nil
    self._commonPlayerHeadNodeScr = nil
end

function UIWorldBossPlayerRankNode:Awake()
    if not self._commonPlayerHeadNodeScr then
        self._commonPlayerHeadNodeScr = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, CommonPlayerHeadNode)
    end
    SetButtonAction(self.BtnDetails, Bind(self, self.OnBtnTeamInfo))
end

---Refresh
---@param data table 
---@param isMe boolean 是否是自己 
function UIWorldBossPlayerRankNode:Refresh(data, isMe, scale)
    if not data then
        return
    end
    self._data = data
    self._isMe = isMe
    self._scale = scale

    if self._isMe then 
        self:FillMeInfo()
    else
        self:FillOtherInfo()
    end
end

function UIWorldBossPlayerRankNode:RefreshBg(isOdd)
    CfUtils.SetActive(self.Imgbg1, isOdd)
    CfUtils.SetActive(self.Imgbg2, not isOdd)
end

