    if self._data.rankNum % 2 == 0 then
        KTool.SetActive(self.Imgbg1, true)
        KTool.SetActive(self.Imgbg2, false)
    else
        KTool.SetActive(self.Imgbg1, false)
        KTool.SetActive(self.Imgbg2, true)
    end
    --CfUtils.FillImage(self.Imgbg1, CfUtils.GetRankListBg(checkNumber(self._data.rankNum)), false)
    local playerInfo = self._data
    if playerInfo then
        if self._commonPlayerHeadNodeScr then
            self._commonPlayerHeadNodeScr:FreshAvatarFrame(playerInfo.avatar, playerInfo.avatarFrame)
            self._commonPlayerHeadNodeScr:SetCallBack(function()


                -- 直接进入 他人的 个人信息界面2D版 
                GameUtils.ShowPlayerInfo( playerInfo.playerId, 
                    {  
                        { id = Constants.UITypeIds.UIWorldBossMainDialog},
                        { id = Constants.UITypeIds.UIWorldBossPlayerRankingsDialog},
                    } 
                )
                -- 下方为旧方案, 暂被替代:
                -- GameUtils.ShowCommonPlayerHeadOption(self.CommonPlayerHeadNode.gameObject, Constants.PlayerHeadOptionType.Common,{
                --     playerId    = playerInfo.playerId,
                --     name        = playerInfo.name,
                --     level       = playerInfo.level,
                --     avatar      = playerInfo.avatar,
                --     avatarFrame = playerInfo.avatarFrame,
                --     exclude = {
                --         { id = Constants.UITypeIds.UIWorldBossMainDialog},
                --         { id = Constants.UITypeIds.UIWorldBossPlayerRankingsDialog},
                --     }
                -- })
            end)
        end
        if self._scale then
            CfUtils.SetScale(self.CommonPlayerHeadNode, self._scale)
        else
            CfUtils.SetScale(self.CommonPlayerHeadNode, (checkNumber(self._data.rankNum) > 3) and Vector3(0.3, 0.3, 1) or Vector3(0.4, 0.4, 1))
        end

        CfUtils.FillText(self.TxtName, playerInfo.name)

        local playerDojo = comp:GetPlayerDojo()
        --KTool.SetActive(self.BtnDetails, not (checkNumber(playerInfo.playerId) == checkNumber(playerDojo.playerId)))
        KTool.SetActive(self.ImgMyself, (checkNumber(playerInfo.playerId) == checkNumber(playerDojo.playerId)))
    end

    self:FillRankReard()
end

function UIWorldBossPlayerRankNode:FillRankReard(isMe, percentageRank)
    local scr = CfUtils.GetLuaScr(self.CommonGoodsList, CommonGoodsList)
    if scr then
        local t = {}
        if isMe then
            percentageRank = checkNumber(percentageRank)
            --在排行榜上
            if percentageRank <= 0 then
                t = QuestConfMgr:GetInstance():GetRankRewardByRankNum(checkNumber(self._data.rankNum))
            else
                local vo = self:GetRankVo(percentageRank)

                local rewardT = CfUtils.Split(vo.reward)
                local rewardNumT = CfUtils.Split(vo.rewardNum)
                for k, v in pairs(rewardT) do
                    table.insert(t, {
                        goodsId = rewardT[k],
                        num = rewardNumT[k],
                    })
                end
            end
        else
            t = QuestConfMgr:GetInstance():GetRankRewardByRankNum(checkNumber(self._data.rankNum))
        end
        local isHaveReard = true

        if not t or table.count(t) <= 0 then
            isHaveReard = false
        end
        KTool.SetActive(self.CommonGoodsList, isHaveReard)
        KTool.SetActive(self.TextNoReward, not isHaveReard)

        if isHaveReard then
            scr:FreshBaseUI(t, false)
        end
    end
end

--绘制自己的
function UIWorldBossPlayerRankNode:FillMeInfo()
    local playerDojo = comp:GetPlayerDojo()
    if checkNumber(self._data.hurt) then
        self._data.score = num_floor(checkNumber(self._data.hurt))
    end
    if checkNumber(self._data.ranking) then
        self._data.rankNum = checkNumber(self._data.ranking)
    end
    CfUtils.FillText(self.TxtDamage, checkNumber(self._data.score))
    CfUtils.FillText(self.Txtranking, checkNumber(self._data.rankNum))
    CfUtils.FillText(self.TextLevel, "Lv."..checkNumber(playerDojo.level))

    local status = checkNumber(self._data.rankNum) > 4 and 5 or checkNumber(self._data.rankNum)
    CfUtils.SetUISwitchImage(self.ItileRank.transform:Find("ImgRank"), status)
    CfUtils.SetUISwitchImage(self.ImgRank, status)

    if self._commonPlayerHeadNodeScr then
        self._commonPlayerHeadNodeScr:FreshBaseUI()
    end
    CfUtils.FillText(self.TxtName, playerDojo.playerName)

    KTool.SetActive(self.ItileRank, checkNumber(self._data.score) ~= 0)
    KTool.SetActive(self.TxtNo, checkNumber(self._data.score) == 0)

    print(table.dump(self._data))
end

function UIWorldBossPlayerRankNode:FillPercentageRank(num)
    num = checkNumber(num)
    CfUtils.SetActive(self.ItileRank.transform:Find("NotEnterNode"), num > 0)
    CfUtils.SetActive(self.ItileRank.transform:Find("NotEnterNode/TxtRanking3"), num > 80)

    if num > 0 then
        local vo = self:GetRankVo(num)
        if vo then
            CfUtils.FillText(self.ItileRank.transform:Find("NotEnterNode/TxtRanking2"), vo.name)
        end
    end
    CfUtils.SetActive(self.BtnDetails, num <= 0 and not self._isMe)

    self:FillRankReard(true, num)

    CfUtils.SetActive(self.Txtranking, num <= 0)
    CfUtils.SetActive(self.ItileRank.transform:Find("ImgRank"), num <= 0)
end

function UIWorldBossPlayerRankNode:GetRankVo(num)
    local t = CfUtils.GetCf(AutoIds.IdSetting978, "WorldBossRankRewardVo", true)
    if not t then
        return nil
    end
    for k, v in pairs(t) do
        if checkNumber(v.type) == 2 then
            if num >= checkNumber(v.upperLimit) and num <= checkNumber(v.lowerLimit) then
                return v
            end
        end
    end
    return nil
end

function UIWorldBossPlayerRankNode:OnBtnTeamInfo()
    if not self._data or not self._data.team then
        self._data = {
    
        }
    end
    if self._isMe then
        local playerDojo = comp:GetPlayerDojo()
        self._data.name = playerDojo.playerName
    end

    local curBossPlanId = worldBossComponent:GetCurBossPlanId()
    local curBossPlanVo = QuestConfMgr:GetInstance():GetWorldBossPlanVo(curBossPlanId)

    GameUtils.ShowCommonTeamsTipsBoard(self.BtnDetails, self._data.team, nil, curBossPlanVo.range, self._data.name)
end

function UIWorldBossPlayerRankNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIWorldBossPlayerRankNode
